demo.css:
.l{list-style:none;margin:0;padding:1rem}.l li{display:flex;justify-content:space-between;padding:.8rem .6rem;border-bottom:1px solid var(--line);font:600 1.3rem var(--font);transition:background .25s,color .25s,padding .25s}
.l span{opacity:0;transform:translateX(-10px);transition:.25s}
.l li:hover,html.hover .l li.on{background:var(--accent);color:var(--accent-fg);padding-left:1rem}.l li:hover span,html.hover .l li.on span{opacity:1;transform:none}
